<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$consents->revoke((int)$user['id'],(int)($_POST['application_id']??0));}
$rows='';foreach($consents->history((int)$user['id']) as $c){$scopes=json_decode((string)$c['scopes_json'],true);$rows.='<tr><td>'.Web::e($c['application_name']).'</td><td>'.Web::e(is_array($scopes)?implode(' ',$scopes):'').'</td><td>'.Web::e($c['granted_at']).'</td><td>'.Web::e($c['revoked_at']?:'Aktywna').'</td><td>'.(!$c['revoked_at']?'<form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.(int)$c['application_id'].'"><button>Cofnij zgodę</button></form>':'').'</td></tr>';}
Web::page('Zgody aplikacji','<div class="page-head"><div><h1>Historia zgód</h1><p>Dane i scopes udostępnione poszczególnym klientom.</p></div></div><div class="table-wrap"><table><thead><tr><th>Aplikacja</th><th>Scopes</th><th>Nadano</th><th>Status</th><th></th></tr></thead><tbody>'.$rows.'</tbody></table></div>',$user);
